  async createExample() {
    const user = new UserModel({
      name: 'John Doe',
      age: 30,
      addresses: [
        { street: '123 Main St', city: 'Anytown', state: 'CA' },
        { street: '456 Elm St', city: 'Anytown', state: 'CA' },
      ],
    });

    const savedUser = await user.save();
    console.log(savedUser);
  }
}
```

