#include <iostream>
#include <string>
#include <vector>

using namespace std;

// Function to generate the Fibonacci sequence
vector<int> generateFibonacciSequence(int n) {
    if (n <= 1) {
        return vector<int>{n};
    } else {
        return vector<int>{generateFibonacciSequence(n - 1)[0], generateFibonacciSequence(n - 2)[1]};
    }
}

int main() {
    int num1, num2;
    cout << "Enter the first two integers: ";
    cin >> num1 >> num2;

    if (cin.fail()) {
        cout << "Invalid input. Please enter only integers." << endl;
        return 1;
    }

    if (num1 < 0 || num2 < 0) {
        cout << "Invalid input. Please enter non-negative integers." << endl;
        return 1;
    }

    int numElements;
    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    if (cin.fail()) {
        cout << "Invalid input. Please enter only integers." << endl;
        return 1;
    }

    if (numElements < 1) {
        cout << "Invalid input. Please enter a positive integer." << endl;
        return 1;
    }

    vector<int> sequence = generateFibonacciSequence(numElements);
    cout << "Fibonacci sequence: ";
    for (int i = 0; i < sequence.size(); i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
