    cin >> sequenceLength;

    if (sequenceLength <= 0) {
        cerr << "Error: Invalid input. Please enter a positive integer." << endl;
        return 1;
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < sequenceLength; ++i) {
        cout << fibonacci(i + 1, num1, num2) << ", ";
    }
    cout << endl;

    return 0;
}
```

This program prompts the user to enter the first two integers and the number of sequence elements to generate. It then generates the Fibonacci sequence using the recursive `fibonacci` function and outputs the sequence with each element separated by a comma and a space. The program includes error handling for invalid inputs, such as non-numeric inputs or negative numbers.

