function determineProtocol(inputData) {
  const { sourceIP, destinationIP, port, payload } = inputData;

  // Check for IPv6 address format
  if (/^([0-9A-Fa-f]{1,4}:){7}([0-9A-Fa-f]{1,4})$/.test(sourceIP)) {
    return 'IPv6';
  }

  // Check for HTTP port
  if (port === 80) {
    return 'HTTP';
  }

  // Check for UDP port
  if (port === 5353) {
    return 'UDP';
  }

  return null;
}

