Here's a simple Google Apps Script that searches for a place name in a column and stores its latitude and longitude in another column. Make sure you have enabled the "Google Maps API" in your project.

```javascript
function searchPlace() {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  var dataRange = sheet.getRange("A1:A"); // Assuming your data range is in column A (A1:A)
  var placeName = dataRange.getValue();

  var geocoder = new google.maps.Geocoder();
  geocoder.geocode({ 'address': placeName }, function(results, status) {
    if (status == 'OK') {
      var latitude = results[0].geometry.location.lat();
      var longitude = results[0].geometry.location.lng();

      var outputRange = sheet.getRange("B1"); // Assuming your output range is in column B (B1:B)
      outputRange.setValue(latitude);
      outputRange = sheet.getRange("C1"); // Assuming your output range is in column C (C1:C)
      outputRange.setValue(longitude);
    } else {
      console.log('Error: ' + status);
    }
  });
}
```

