                    .withSchedule(SimpleTrigger.SimpleTriggerBuilder.daily())
                    .build();
            scheduler.scheduleJob(jobDetail, trigger);

            // Start the Scheduler
            scheduler.start();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
