def calculate_area(shape: str, length: float, width: float) -> float:
    """Calculates the area of a shape based on its length and width."""
    if shape == "rectangle":
        return length * width
    elif shape == "circle":
        return 3.14 * (length ** 2)
    else:
        raise ValueError("Invalid shape.")

def check_age(age: int) -> bool:
    """Checks if a person is old enough to vote based on their age."""
    if age >= 18:
        return True
    else:
        return False

def convert_temperature(temp: float, unit: str) -> float:
    """Converts a temperature from one unit to another."""
    if unit == "Celsius":
        return temp * 9 / 5 + 32
    elif unit == "Fahrenheit":
        return (temp - 32) * 5 / 9
    else:
        raise ValueError("Invalid temperature unit.")
```

