```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    char *cstr = (char *)malloc((argc + 1) * sizeof(char));
    int i;

    for (i = 0; i < argc; i++) {
        strcat(cstr, argv[i]);
        if (i != argc - 1) {
            strcat(cstr, " ");
        }
    }
    cstr[strlen(cstr)] = '\0';

    printf("C string: %s\n", cstr);

    free(cstr);
    return 0;
}
