Here's a simple decorator for Nest.js middleware that checks the `NODE_ENV` variable and calls the next middleware function or returns `false` based on the environment:

```typescript
import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';

@Injectable()
export class EnvGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const req = context.switchToHttp().getRequest();
    const nodeEnv = process.env.NODE_ENV;

    if (nodeEnv === 'true') {
      return true;
    } else {
      return false;
    }
  }
}
```

Now you can use this guard in your Nest.js controller to restrict access to certain endpoints based on the environment:

```typescript
import { Controller, Get, UseGuards } from '@nestjs/common';
import { EnvGuard } from './env-guard';

@Controller('api')
export class ApiController {
  @Get()
