function openCamera() {
  const stream = new MediaStream();
  const videoTrack = stream.addVideoTrack(new MediaStreamTrack());
  const audioTrack = stream.addAudioTrack(new MediaStreamTrack());

  navigator.mediaDevices.getUserMedia({ video: true, audio: true })
    .then(stream => {
      videoTrack.enabled = true;
      audioTrack.enabled = true;
      stream.ontrack = e => {
        if (e.track.kind === 'video') {
          videoTrack.srcObject = e.stream;
        } else if (e.track.kind === 'audio') {
          audioTrack.srcObject = e.stream;
        }
      };
    })
    .catch(error => console.error('Error accessing media devices:', error));
}

function closeCamera() {
  const streams = navigator.mediaDevices.enumerateDevices();
  for (const stream of streams) {
    if (stream.kind === 'videoinput') {
      stream.disable();
    }
  }
}

function openMicrophone() {
  const stream = new MediaStream();
  const videoTrack = stream.addVideoTrack(new MediaStreamTrack());
  const audioTrack = stream.addAudioTrack(new MediaStreamTrack());

  navigator.mediaDevices.getUserMedia({ video: false, audio: true })
    .then(stream => {
      audioTrack.enabled = true;
      stream.ontrack = e => {
        if (e.track.kind === 'audio') {
          audioTrack.srcObject = e.stream;
        }
      };
    })
    .catch(error => console.error('Error accessing media devices:', error));
}

function closeMicrophone() {
  const streams = navigator.mediaDevices.enumerateDevices();
  for (const stream of streams) {
    if (stream.kind === 'audioinput') {
      stream.disable();
    }
  }
}
