import { useCombobox } from 'downshift';
import axios from 'axios';

interface Email {
  id: number;
  email: string;
}

const EmailsInput = () => {
  const [emails, setEmails] = React.useState([]);
  const [searchTerm, setSearchTerm] = React.useState('');

  const fetchEmails = async (prefix: string) => {
    try {
      const response = await axios.get(`/api/emails?prefix=${prefix}`);
      setEmails(response.data);
    } catch (error) {
      console.error(error);
    }
  };

  const { isOpen, selectedItem, getMenuProps, getComboboxProps, getItemProps } = useCombobox({
    items: emails,
    getItemValue: (item: Email) => item.email,
    onSelect: (selectedItem) => {
      setSearchTerm(selectedItem.email);
    },
  });

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(event.target.value);
    fetchEmails(event.target.value);
  };

  return (
    <div {...getComboboxProps()}>
      <input
        type="text"
        value={searchTerm}
        onChange={handleInputChange}
        {...getComboboxProps()}
      />
      {isOpen && (
        <ul {...getMenuProps()}>
          {emails.map((email) => (
            <li key={email.id} {...getItemProps({ item: email })}>
              {email.email}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default EmailsInput;
```

