Here's a concise and elegant C# code that leverages the Accord.NET library to train and implement the Naive Bayes algorithm for text classification:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Accord.MachineLearning.Bayesian;
using Accord.MachineLearning.Transformations;

namespace TextClassification
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load the dataset
            var dataset = new List<(string sentence, string category)>
            {
                ("The sports game was exciting", "Sports"),
                ("The political rally was heated", "Politics"),
                ("The entertainment show was hilarious", "Entertainment")
            };

            // Transform the dataset into a matrix of word counts
            var vectorizer = new CountVectorizer();
            var matrix = vectorizer.Transform(dataset);

            // Create a Naive Bayes classifier
            var naiveBayes = new NaiveBayes();

            // Fit the model on the labeled dataset
            naiveBayes.Fit(matrix, dataset.Select(x => x.category));

            // Predict the labels of new observations
            var newObservations = new List<(string sentence, string category)>
            {
                ("The sports game was boring", "Sports"),
                ("The political rally was peaceful", "Politics"),
                ("The entertainment show was disappointing", "Entertainment")
            };

            var predictions = naiveBayes.Predict(newObservations.Select(x => x.sentence));

            // Output the predicted labels
            foreach (var prediction in predictions)
            {
                Console.WriteLine($"{prediction.sentence} - {prediction.category}");
            }
        }
    }
}
```

