Here's a simple React utility to remove widows. This component will check if the text contains any words that are wider than the container and adjust the font size accordingly.

```javascript
import React, { useEffect, useState } from 'react';

const RemoveWidows = ({ children }) => {
  const [fontSize, setFontSize] = useState(16);

  useEffect(() => {
    const checkWidth = () => {
      const container = document.querySelector('.remove-widows');
      const text = container.textContent;
      const words = text.split(' ');

      let maxWidth = 0;

      words.forEach((word) => {
        const wordWidth = word.offsetWidth;
        if (wordWidth > maxWidth) {
          maxWidth = wordWidth;
        }
      });

      const newFontSize = Math.min(fontSize * (container.offsetWidth / maxWidth), 24);
      setFontSize(newFontSize);
    };

    checkWidth();
  }, [fontSize]);

  return (
    <div className="remove-widows" style={{ fontSize }}>
      {children}
    </div>
  );
};

export default RemoveWidows;
```

To use this component, simply wrap your text with it:

