		if containsNegativeWord(word) || containsNotAndNegativeWord(word) {
			return true
		}
	}
	return false
}

func containsNegativeWord(word string) bool {
	for _, negWord := range negativeWords {
		if word == negWord || word == "-" + negWord {
			return true
		}
	}
	return false
}

func containsNotAndNegativeWord(word string) bool {
	parts := strings.Split(word, " ")
	if len(parts) != 2 {
		return false
	}
	return parts[0] == "not" && containsNegativeWord(parts[1])
}

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	if isDoubleNegative(sentence) {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}
```

